using UnityEngine;
namespace Veilbound {public partial class VeilGame {
 static Settlement QueueSample(){var c=Settlement.NewCamp();c.mine=3;c.blacksmith=4;c.huntersLodge=c.weaver=3;c.clothier=2;c.tailor=c.leatherworker=2;c.library=1;c.timber=2;c.quarry=1;c.wood=c.stone=1000;c.EnsureGear();c.EnsureIndustry();c.EnsureResearch();for(int i=0;i<c.researchRanks.Length;i++)c.researchRanks[i]=LibraryResearch.IsSlotResearch(LibraryResearch.Ids[i])?0:10;c.EnsureMineOrders();c.mineOrders.Clear();for(int f=0;f<3;f++){Array.Clear(c.Allocation(f),0,c.Allocation(f).Length);for(int i=0;i<ResourceNamesLength(f);i++)c.AddResource(f,i,-c.ResourceAmount(f,i));}for(int i=0;i<WeaponRules.Count;i++)c.metalBars[i]=0;return c;}
 static void FundPlateSupports(Settlement c,int metal,int slot,int count=1){var recipe=c.PlateRecipe(slot,metal);for(int i=1;i<recipe.Length;i++)c.AddResource(recipe[i].family,recipe[i].index,recipe[i].amount*count);}
 static int ResourceNamesLength(int f)=>Settlement.ResourceNames[f].Length;
 static void QueueCheck(bool pass,string message){Require(pass,"Settlement queue: "+message);Debug.Log("QUEUE_CHECK_PASS: "+message);}
 void CheckSettlementQueue(){
  var c=QueueSample();c.AddResource(0,0,4);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.RefreshSettlementPlan(true);QueueCheck(c.dependencyMineResource<0,"existing ore skips mining");c.Tick(3600,1);QueueCheck(c.settlementQueue.Count==0&&c.OwnsPlate(3,0)&&c.ResourceAmount(0,0)==0,"ore is refined and queued armour completes");
  c=QueueSample();FundPlateSupports(c,0,3);c.metalBars[0]=4;c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(.1,1);QueueCheck(c.OwnsPlate(3,0)&&c.dependencyMineResource<0&&c.dependencyBarOrder==null,"existing bars skip the entire supply chain");
  c=QueueSample();c.QueueSettlementJob(2,"",2,0,1,0,out _);c.Tick(100*60,1);QueueCheck(c.settlementQueue.Count==0&&c.smithOrders.Count==0&&c.metalBars[2]==1&&c.metalBars[0]==0&&c.metalBars[1]==0&&c.ResourceTotal(0)==0,"recursive bronze recipe mines and refines only missing inputs");
  c=QueueSample();c.QueueMining(1,1,out _);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(.5*60,1);QueueCheck(c.mineOrders.Count==1&&c.ResourceAmount(0,0)==0&&c.dependencyMineWork==Settlement.MineUnitWork(0),"manual mining preempts automatic demand");
  c=QueueSample();c.QueueMining(0,4,out _);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.RefreshSettlementPlan();QueueCheck(c.dependencyMineResource<0,"incoming manual ore prevents duplicate mining");
  c=QueueSample();FundPlateSupports(c,0,3,2);c.metalBars[0]=4;c.QueueSettlementJob(3,"",0,3,1,0,out _);c.QueueSettlementJob(3,"",0,4,1,0,out _);c.RefreshSettlementPlan(true);QueueCheck(c.OwnsPlate(3,0)&&!c.OwnsPlate(4,0)&&c.dependencyMineResource==0,"shared stock is reserved in queue order");
  c=QueueSample();c.Allocate(1,1,c.Capacity(1));c.Allocate(2,1,c.Capacity(2));c.QueueSettlementJob(0,"housing",0,0,1,0,out _);c.Tick(120,1);QueueCheck(c.ResourceAmount(1,0)==0&&c.ResourceAmount(2,0)==0&&c.huntEffort[1]==c.Capacity(1),"full manual allocations block automatic gathering without being overwritten");
  Array.Clear(c.huntEffort,0,c.huntEffort.Length);Array.Clear(c.textileEffort,0,c.textileEffort.Length);c.Tick(100*60,1);QueueCheck(c.housingTier==1&&c.ResourceAmount(1,0)<1e-7&&c.ResourceAmount(2,0)<1e-7,"spare capacity supplies only required hides and textiles for construction");
  c=QueueSample();c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(70,1);var loaded=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(40*60,1);loaded.Tick(40*60,1);QueueCheck(c.OwnsPlate(3,0)&&loaded.OwnsPlate(3,0)&&Math.Abs(c.ResourceAmount(0,0)-loaded.ResourceAmount(0,0))<1e-8,"queue and partial automatic work survive save/load");
  c=QueueSample();c.AddResource(0,0,4);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(.1,1);QueueCheck(c.dependencyBarOrder!=null,"automatic refining tracks paid ingredients");c.RemoveSettlementJob(c.settlementQueue[0].id);QueueCheck(c.dependencyBarOrder==null&&c.ResourceAmount(0,0)==4,"cancelling the final goal refunds unfinished automatic refining");
  c=QueueSample();c.QueueSettlementJob(2,"",2,0,1,0,out _);var stepped=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(40*60,1);for(int i=0;i<2400;i++)stepped.Tick(1,1);for(int f=0;f<4;f++){int count=f==3?WeaponRules.Count:ResourceNamesLength(f);for(int i=0;i<count;i++)QueueCheck(Math.Abs(c.ResourceAmount(f,i)-stepped.ResourceAmount(f,i))<1e-6,"bulk/frame supply matches "+f+"/"+i);}
  c=QueueSample();c.researchRanks[LibraryResearch.Index("mine")]=1;c.QueueSettlementJob(1,"mine",0,0,1,2,out _);c.QueueSettlementJob(0,"mine",0,0,1,0,out _);c.Tick(160*60,1);QueueCheck(c.ResearchRank("mine")==2,"research acquires its own missing bars and completes");
  c=QueueSample();c.QueueSettlementJob(3,"",9,3,1,0,out _);c.Tick(60,1);QueueCheck(!c.OwnsPlate(3,9)&&c.settlementQueue.Count==1,"locked recipes stay queued without bypassing prerequisites");
  c=QueueSample();c.AddRepeatStep(false,1,1,out _);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(40*60,1);QueueCheck(c.OwnsPlate(3,0)&&c.ResourceAmount(0,1)>0,"fallback resumes after city demand is satisfied");
  c=QueueSample();c.AddResource(0,0,4);c.QueueBars(0,4,out _);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.RefreshSettlementPlan();QueueCheck(c.dependencyMineResource<0&&!c.HasDependencyBars,"incoming bars prevent redundant mining and refining");
  c=QueueSample();c.AddResource(0,1,1);c.QueueBars(1,1,out _);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.Tick(30,1);QueueCheck(c.smithOrders.Count==1&&c.dependencyBarOrder==null,"manual refining runs before demand refining");
  c=QueueSample();c.QueueSettlementJob(3,"",0,3,1,0,out _);c.QueueSettlementJob(3,"",1,3,1,0,out _);int first=c.settlementQueue[0].id,second=c.settlementQueue[1].id;c.MoveSettlementJob(second,-1);c.RefreshSettlementPlan();QueueCheck(c.dependencyMineResource==1,"reordering changes automatic material priority");
  c=QueueSample();c.AddResource(0,0,4);c.QueueSettlementJob(3,"",0,3,1,0,out _);c.QueueSettlementJob(3,"",1,3,1,0,out _);first=c.settlementQueue[0].id;c.Tick(.1,1);c.RemoveSettlementJob(first);c.RefreshSettlementPlan();QueueCheck(c.dependencyBarOrder==null&&c.ResourceAmount(0,0)==4,"cancelling a goal refunds its orphaned refining while other goals remain");
  c=QueueSample();c.mine=1;c.researchRanks[LibraryResearch.Index("mine")]=1;c.wood=8;c.stone=4;c.metalBars[0]=2;c.QueueSettlementJob(0,"mine",0,0,1,0,out _);c.QueueSettlementJob(1,"mine",0,0,1,2,out _);c.Tick(.01,1);QueueCheck(c.activeResearch=="mine"&&c.activeConstruction=="","blocked first build yields materials to runnable research below it");
  c=QueueSample();c.mine=1;c.researchRanks[LibraryResearch.Index("mine")]=1;c.wood=100;c.stone=100;c.metalBars[0]=2;c.QueueSettlementJob(0,"mine",0,0,1,0,out _);c.QueueSettlementJob(1,"mine",0,0,1,2,out _);c.Tick(50*60,1);QueueCheck(c.mine==2&&c.ResearchRank("mine")==2&&c.settlementQueue.Count==0,"first build is retried after lower-priority prerequisite research finishes");
  c=QueueSample();c.QueueSettlementJob(3,"",2,2,1,0,out _);foreach(var part in c.LightGearRecipe(3,1,1))c.AddResource(part.family,part.index,part.amount);c.AddResource(3,0,c.PlateRecipe(2,2)[0].amount);c.QueueSettlementJob(5,"",1,3,1,0,out _);c.Tick(.01,1);QueueCheck(c.Owned(3,1)>0&&c.settlementQueue.Count==1,"ready Clothier work runs while the first Blacksmith job waits");
  Debug.Log("VEILBOUND_SETTLEMENT_QUEUE_LOGIC_PASS");
 }
 IEnumerator SettlementQueueReview(){
  yield return null;combatReviewFreeze=true;CheckSettlementQueue();CheckResourcePriorities();CheckManualStockpiles();CheckProductionSlots();CheckRefiningSlots();CheckMaterialProcessing();ReturnHome();city=QueueSample();tab=2;SetState(ScreenState.Settlement);
  city.QueueSettlementJob(3,"",2,2,1,0,out _);city.QueueSettlementJob(0,"housing",0,0,1,0,out _);city.QueueSettlementJob(1,"mine",0,0,1,0,out _);city.QueueMining(0,20,out _);city.AddRepeatStep(false,1,10,out _);city.Tick(60,1);
  string output=Path.Combine(Application.dataPath,"..","Smoke","SettlementQueue");Directory.CreateDirectory(output);OpenProducer(0);yield return CardScreenshot(Path.Combine(output,"01-mine-demand.png"));OpenSettlementQueue();yield return CardScreenshot(Path.Combine(output,"02-work-queue.png"));
