  city=ResourcePrioritySample();city.RefreshSettlementPlan();OpenSettlementQueue();priorityResourceFamily=3;priorityResourceIndex=1;settlementQueueScroll=Vector2.zero;yield return CardScreenshot(Path.Combine(output,"03-copper-priorities.png"));CloseSettlementQueue();
  city=StockpileSample();city.AddRepeatStep(false,7,10,out _);city.mineScheduleManualPriority=true;city.Tick(60,1);OpenProducer(0);producerItem=7;producerAmount="10";yield return CardScreenshot(Path.Combine(output,"04-manual-stockpile.png"));
  yield return ProductionSlotScreenshots(output);yield return RefiningSlotScreenshots(output);yield return MaterialProcessingScreenshots(output);
  Debug.Log("VEILBOUND_SETTLEMENT_QUEUE_RUNTIME_PASS");File.WriteAllText(Path.Combine(output,"PASS.txt"),"PASS: recursive supply, stock/incoming reservations, manual priority, spare capacity, cancellation, saves, locks, fallback, frame invariance and mine/queue screens.");Application.Quit(0);
 }
